(()=>{const base='/child-advocacy-site/news/vote-for-children-future-20261128/';const items={'zh-Hant':{href:base,title:'為下一代投票：別讓孩子的未來只能靠運氣',alt:'多名孩子在戶外微笑舉手，旁有提醒民眾投票的文字圖像。'},'zh-Hans':{href:base+'zh-Hans/',title:'为下一代投票：别让孩子的未来只能靠运气',alt:'孩子们在户外微笑举手，旁有提醒公众投票的文字图像。'},en:{href:base+'en/',title:'Vote with the next generation in mind',alt:'Children outdoors beside a graphic encouraging people to vote.'},ja:{href:base+'ja/',title:'次世代を思って投票する',alt:'屋外で笑顔を見せる子どもたちと、投票を呼びかける図案。'}};const image='/child-advocacy-site/assets/images/vote-for-children-future-20261128.jpg';const locale=()=>document.documentElement.lang==='zh-Hans'||new URLSearchParams(location.search).get('lang')==='zh-Hans'?'zh-Hans':items[document.documentElement.lang]?document.documentElement.lang:'zh-Hant';const mount=()=>{const grid=document.querySelector('#home-latest-25-20261118 .home-latest-25-grid');if(!grid||grid.querySelector('[data-vote-for-children]'))return false;const item=items[locale()],a=document.createElement('a');a.className='home-latest-25-card';a.dataset.voteForChildren='1';a.href=item.href;a.setAttribute('aria-label',item.title);a.innerHTML='<img src="'+image+'" alt="'+item.alt+'"><time datetime="2026-11-28">2026.11.28</time><strong>'+item.title+'</strong>';grid.insertBefore(a,grid.firstElementChild);return true};const observe=()=>{if(mount())return;new MutationObserver((_,o)=>{if(mount())o.disconnect()}).observe(document.documentElement,{childList:true,subtree:true})};addEventListener('cpa-home-latest-ready',mount);document.readyState==='loading'?addEventListener('DOMContentLoaded',observe,{once:true}):observe()})();
